  `book_id` bigint NOT NULL AUTO_INCREMENT COMMENT '图书ID',
  `book_name` varchar(200) NOT NULL COMMENT '图书名称',
  `book_author` varchar(100) DEFAULT NULL COMMENT '作者',
  `book_isbn` varchar(30) DEFAULT NULL COMMENT 'ISBN编号',
