CREATE TABLE `lib_cultivation_log` (
  `log_id` bigint NOT NULL AUTO_INCREMENT COMMENT '流水ID',
  `user_id` bigint NOT NULL COMMENT '读者ID',
  `change_type` varchar(20) DEFAULT NULL COMMENT '类型 borrow/return_on_time/return_overdue/sign/purify',
