  `demon_change` int DEFAULT '0' COMMENT '魔性变化',
  `reason` varchar(255) DEFAULT NULL COMMENT '事由',
  `create_time` datetime DEFAULT NULL COMMENT '记录时间',
  PRIMARY KEY (`log_id`),
  KEY `idx_cult_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8mb3 COMMENT='读者修行流水';
