DROP TABLE IF EXISTS `lib_fine`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lib_fine` (
  `fine_id` bigint NOT NULL AUTO_INCREMENT COMMENT '罚金ID',
  `borrow_id` bigint NOT NULL COMMENT '借阅记录ID(关联lib_borrow)',
  `user_id` bigint NOT NULL COMMENT '读者ID(关联lib_user)',
  `book_id` bigint NOT NULL COMMENT '图书ID(关联lib_book)',
  `overdue_days` int DEFAULT '0' COMMENT '逾期天数',
  `fine_amount` decimal(10,2) DEFAULT '0.00' COMMENT '罚金金额',
  `fine_status` char(1) DEFAULT '0' COMMENT '状态 0未缴 1已缴',
  `pay_time` datetime DEFAULT NULL COMMENT '缴纳时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`fine_id`),
  KEY `idx_fine_user` (`user_id`),
  KEY `idx_fine_borrow` (`borrow_id`),
  KEY `idx_fine_status` (`fine_status`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='借阅罚金表';
