DROP TABLE IF EXISTS `lib_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lib_user` (
  `user_id` bigint NOT NULL AUTO_INCREMENT COMMENT '读者ID',
  `user_name` varchar(50) NOT NULL COMMENT '读者姓名',
  `user_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `user_email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `user_status` char(1) DEFAULT '0' COMMENT '状态 0正常 1禁用',
  `merit_points` int NOT NULL DEFAULT '0' COMMENT '功德值（决定境界）',
  `demon_value` int NOT NULL DEFAULT '0' COMMENT '魔性值（决定魔丸/灵珠）',
  `cultivation_level` int NOT NULL DEFAULT '0' COMMENT '境界等级 0凡人1道童2天兵3仙将4三坛海会大神5魔童战神',
  `last_sign_date` date DEFAULT NULL COMMENT '最后签到日期',
  `last_fortune_date` datetime DEFAULT NULL COMMENT '每日奇遇日期',
  `sys_user_id` bigint DEFAULT NULL COMMENT '关联系统用户ID',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `forgive_tokens` int NOT NULL DEFAULT '0' COMMENT '免罚令数量',
  `box_date` date DEFAULT NULL COMMENT '开仙丹盲盒日期',
  `box_count_today` int NOT NULL DEFAULT '0' COMMENT '当日开盲盒次数',
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uk_lib_user_sys` (`sys_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='图书读者表';
/*!40101 SET character_set_client = @saved_cs_client */;

