UNLOCK TABLES;
DROP TABLE IF EXISTS `sys_notice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_notice` (
  `notice_id` int NOT NULL AUTO_INCREMENT COMMENT '公告ID',
  `notice_title` varchar(50) NOT NULL COMMENT '公告标题',
  `notice_type` char(1) NOT NULL COMMENT '公告类型（1通知 2公告）',
  `notice_content` longblob COMMENT '公告内容',
  `status` char(1) DEFAULT '0' COMMENT '公告状态（0正常 1关闭）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`notice_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb3 COMMENT='通知公告表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sys_notice` WRITE;
/*!40000 ALTER TABLE `sys_notice` DISABLE KEYS */;
INSERT INTO `sys_notice` VALUES (1,'新书到馆通知：120 种新书已上架','1',_binary '<p>各位读者：</p><p>本批新到图书共 120 种，涵盖计算机、文学、历史、经济等类别，已全部上架至 A 区、B 区书架，欢迎前来借阅。</p><p>其中重点推荐：《深入理解计算机系统（第3版）》《三体》《人类简史》等热门图书。</p>','0','admin','2026-10-20 08:28:32','admin','2026-10-27 09:40:40','管理员'),(2,'借阅到期提醒','2',_binary '亲爱的读者：您有部分图书即将到期，请尽快归还或办理续借手续。\n逾期未还将暂停借阅权限，并按每日 0.1 元收取滞纳金。\n如有疑问，请联系流通部服务台','0','admin','2026-10-20 08:28:32','admin','2026-10-27 09:40:24','管理员'),(3,'图书馆开放时间调整通知','1',_binary '<p><strong>﻿自本月起<s><u>，图书馆开放时间调整如下：</u></s></strong></p><p><strong><s><u>周一至周日 8:30 - 21:00</u></s></strong></p><p><strong>法定节假日开放时间另行通</strong>知。</p>','0','admin','2026-10-20 08:28:32','admin','2026-10-28 20:51:38','管理员'),(16,'预约到书提醒：《百年孤独》','2',_binary '您预约的图书已到书，请在 3 天内到馆借出，超期预约将自动失效。','0','system','2026-10-29 18:15:49','',NULL,NULL),(18,'【管理端指南】系统功能 · 自动化规则与判定口径','2',_binary '<h3><span style=\"color: rgb(212, 50, 31);\">一、首页数据看板（自动统计）</span></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">借阅趋势 / 热门图书 / 逾期率 / 魔丸灵珠分布 / 馆藏册数</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">口径：馆藏册数 = 全部图书库存总册数；在借 = 未还借阅笔数（借阅中 + 逾期）；逾期率 = 逾期笔数 ÷ 在借笔数</span></li></ol><h3><span style=\"color: rgb(212, 50, 31);\">二、管理功能（手动操作）</span></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">图书管理、读者管理、借阅记录、预约管理、罚金管理、逾期处理、公告管理</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">借阅记录支持书名 + 读者姓名搜索；罚金管理支持读者姓名过滤；逾期处理集中查看</span></li></ol><h3><span style=\"color: rgb(212, 50, 31);\">三、自动执行规则（系统定时/触发）</span></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">逾期魔性结算：每逾期一天魔性 +5（登录/扫描时幂等推进），生成罚金时再按罚金金额 ×10 加魔性</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">罚金生成：逾期还书自动按 0.5 元/天生成未缴罚金</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">账号冻结：逾期超 3 天自动冻结（读者提示联系管理员），还书后自动解冻</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">预约到书提醒：预约书到馆后读者登录自动弹窗</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">罚金催缴提醒：读者登录自动弹窗列出未缴罚金；管理端也可手动发布公告催缴</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">修行结算：借书 +5 功德；按时还书 +10 且魔性 -2；逾期还书仅 +2；签到 +15；每日奇遇随机加减功德</span></li></ol><h3><span style=\"color: rgb(212, 50, 31);\">四、魔丸与灵珠判定口径（全局生效）</span></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">灵珠：无当前逾期、无未缴罚金、魔性为 0</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">魔丸：当前逾期大于 0，或未缴罚金大于 0，或魔性 ≥ 30，任一命中即魔丸</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">灵珠：无逾期、无未缴罚金且魔性低于 30（有魔性但未达 30 也算灵珠）</span></li></ol><h3><span style=\"color: rgb(212, 50, 31);\">五、借阅约束</span></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">同一读者对同一本书未归还前不可再借；一本书库存借完时自动提示等待归还或预约</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(48, 49, 51);\">借期 30 天、读者上限 5 本、续借 1 次 +15 天</span></li></ol>','0','admin','2026-10-30 14:11:04','admin','2026-10-30 14:14:02','管理端指南公告'),(19,'【读者指南】我的功能 · 魔丸灵珠判定与自动提醒','2',_binary '<div style=\"font-family:Microsoft YaHei, sans-serif; line-height:1.9; color:#303133;\">\n<h3 style=\"margin:6px 0; color:#d4321f;\">一、我的修行（读者中心）</h3>\n<ul>\n<li>功德 / 境界 / 称号 / 封神榜；签到手动 +15 功德</li>\n<li>每日奇遇：登录自动随机触发，仙丹 +30 功德 或 天劫 -10 功德，每天最多一次</li>\n<li>一念成仙：手动净化，每 10 功德洗 1 点魔性，魔丸也能回头</li>\n</ul>\n<h3 style=\"margin:6px 0; color:#d4321f;\">二、借阅与预约</h3>\n<ul>\n<li>借期 30 天，最多同时 5 本，可续借 1 次（延长 15 天）</li>\n<li>同一本书未归还前不能重复借</li>\n<li>预约：书到馆后登录自动弹窗提醒，请及时取书</li>\n</ul>\n<h3 style=\"margin:6px 0; color:#d4321f;\">三、魔丸与灵珠判定</h3>\n<ul>\n<li>我是灵珠：无当前逾期、无未缴罚金、魔性低于 30</li>\n<li>我是魔丸：有当前逾期，或有未缴罚金，或魔性 ≥ 30</li>\n<li>变回灵珠：按时还书（魔性 -2）、缴清罚金（收银台一键缴纳）、用功德净化魔性</li>\n</ul>\n<h3 style=\"margin:6px 0; color:#d4321f;\">四、自动提醒（登录后自动弹窗）</h3>\n<ul>\n<li>预约到书提醒；未缴罚金催缴提醒；账号冻结提示</li>\n</ul>\n<h3 style=\"margin:6px 0; color:#d4321f;\">五、冻结规则</h3>\n<ul>\n<li>逾期超 3 天账号自动冻结，请及时联系管理员；还书后自动解冻</li>\n</ul>\n<h3 style=\"margin:6px 0; color:#d4321f;\">六、演示账号</h3>\n<ul>\n<li>读者密码统一 123456，用户名为读者中文名；含 10 位纯净灵珠读者：林清风、苏婉清、顾云舟、白若溪、陆明轩、楚灵薇、沈砚秋、唐婉如、叶千帆、韩疏影</li>\n</ul>\n</div>','0','admin','2026-10-30 14:11:04','',NULL,'读者指南公告'),(20,'【功能上新】仙丹盲盒 · 免罚令','2',_binary '<div style=\"font-family:Microsoft YaHei, sans-serif; line-height:1.9; color:#303133;\">\n<h3 style=\"margin:6px 0; color:#d4321f;\">一、开仙丹盲盒（读者中心 · 新）</h3>\n<ul>\n<li>价格：20 功德/次</li>\n<li>奖励：随机 +10 ~ +200 功德，抽到多少全凭仙缘</li>\n<li>次数：每日最多 3 次，跨天自动重置</li>\n<li>限制：魔丸不可抽——有当前逾期、或未缴罚金、或魔性 ≥ 30 的读者会被拦下，先还书缴罚金或净化魔性再来</li>\n</ul>\n<h3 style=\"margin:6px 0; color:#d4321f;\">二、免罚令（读者中心 · 新）</h3>\n<ul>\n<li>价格：50 功德兑换 1 张，长期持有</li>\n<li>效果：缴罚金时自动抵消一次，无需支付，收银台会显示本次将自动抵消</li>\n<li>用法：在「我的罚金」收银台点击「我已支付」即可，系统自动消耗免罚令并提示</li>\n</ul>\n<h3 style=\"margin:6px 0; color:#d4321f;\">三、入口与提示</h3>\n<ul>\n<li>入口：登录后进入读者中心，修行面板即可看到「仙丹盲盒（剩 X）」与「兑换免罚令（持 X）」按钮</li>\n<li>功德不足 / 次数用尽 / 魔丸身份均有弹窗提示</li>\n<li>盲盒与兑换记录均写入修行日志，可在读者中心查看功德明细</li>\n</ul>\n</div>','0','admin','2026-10-30 15:08:23','',NULL,'功能上新：仙丹盲盒与免罚令');
/*!40000 ALTER TABLE `sys_notice` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `sys_notice_read`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_notice_read` (
  `read_id` bigint NOT NULL AUTO_INCREMENT COMMENT '已读主键',
  `notice_id` int NOT NULL COMMENT '公告id',
  `user_id` bigint NOT NULL COMMENT '用户id',
  `read_time` datetime NOT NULL COMMENT '阅读时间',
  PRIMARY KEY (`read_id`),
  UNIQUE KEY `uk_user_notice` (`user_id`,`notice_id`) COMMENT '同一用户同一公告只记录一次'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='公告已读记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sys_notice_read` WRITE;
/*!40000 ALTER TABLE `sys_notice_read` DISABLE KEYS */;
/*!40000 ALTER TABLE `sys_notice_read` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `sys_oper_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_oper_log` (
  `oper_id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志主键',
  `title` varchar(50) DEFAULT '' COMMENT '模块标题',
  `business_type` int DEFAULT '0' COMMENT '业务类型（0其它 1新增 2修改 3删除）',
  `method` varchar(200) DEFAULT '' COMMENT '方法名称',
  `request_method` varchar(10) DEFAULT '' COMMENT '请求方式',
  `operator_type` int DEFAULT '0' COMMENT '操作类别（0其它 1后台用户 2手机端用户）',
  `oper_name` varchar(50) DEFAULT '' COMMENT '操作人员',
  `dept_name` varchar(50) DEFAULT '' COMMENT '部门名称',
  `oper_url` varchar(255) DEFAULT '' COMMENT '请求URL',
  `oper_ip` varchar(128) DEFAULT '' COMMENT '主机地址',
  `oper_location` varchar(255) DEFAULT '' COMMENT '操作地点',
  `oper_param` varchar(2000) DEFAULT '' COMMENT '请求参数',
  `json_result` varchar(2000) DEFAULT '' COMMENT '返回参数',
  `status` int DEFAULT '0' COMMENT '操作状态（0正常 1异常）',
  `error_msg` varchar(2000) DEFAULT '' COMMENT '错误消息',
  `oper_time` datetime DEFAULT NULL COMMENT '操作时间',
  `cost_time` bigint DEFAULT '0' COMMENT '消耗时间',
  PRIMARY KEY (`oper_id`),
  KEY `idx_sys_oper_log_bt` (`business_type`),
  KEY `idx_sys_oper_log_s` (`status`),
  KEY `idx_sys_oper_log_ot` (`oper_time`)
) ENGINE=InnoDB AUTO_INCREMENT=206 DEFAULT CHARSET=utf8mb3 COMMENT='操作日志记录';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sys_oper_log` WRITE;
/*!40000 ALTER TABLE `sys_oper_log` DISABLE KEYS */;
INSERT INTO `sys_oper_log` VALUES (100,'代码生成',6,'com.ruoyi.generator.controller.GenController.importTableSave()','POST',1,'admin','研发部门','/tool/gen/importTable','127.0.0.1','内网IP','{\"tables\":\"lib_book,lib_borrow,lib_user\",\"tplWebType\":\"element-ui\"}','{\"msg\":\"操作成功\",\"code\":200}',0,NULL,'2026-10-20 08:34:19',152),(101,'代码生成',2,'com.ruoyi.generator.controller.GenController.synchDb()','GET',1,'admin','研发部门','/tool/gen/synchDb/lib_book','127.0.0.1','内网IP','{}','{\"msg\":\"操作成功\",\"code\":200}',0,NULL,'2026-10-20 08:34:27',40),(102,'代码生成',2,'com.ruoyi.generator.controller.GenController.synchDb()','GET',1,'admin','研发部门','/tool/gen/synchDb/lib_borrow','127.0.0.1','内网IP','{}','{\"msg\":\"操作成功\",\"code\":200}',0,NULL,'2026-10-20 08:34:31',34),(103,'代码生成',2,'com.ruoyi.generator.controller.GenController.synchDb()','GET',1,'admin','研发部门','/tool/gen/synchDb/lib_user','127.0.0.1','内网IP','{}','{\"msg\":\"操作成功\",\"code\":200}',0,NULL,'2026-10-20 08:34:32',30),(104,'代码生成',8,'com.ruoyi.generator.controller.GenController.batchGenCode()','GET',1,'admin','研发部门','/tool/gen/batchGenCode','127.0.0.1','内网IP','{\"tables\":\"lib_book\"}',NULL,0,NULL,'2026-10-20 08:45:13',168),(105,'代码生成',8,'com.ruoyi.generator.controller.GenController.batchGenCode()','GET',1,'admin','研发部门','/tool/gen/batchGenCode','127.0.0.1','内网IP','{\"tables\":\"lib_borrow\"}',NULL,0,NULL,'2026-10-20 08:47:14',38),(106,'代码生成',8,'com.ruoyi.generator.controller.GenController.batchGenCode()','GET',1,'admin','研发部门','/tool/gen/batchGenCode','127.0.0.1','内网IP','{\"tables\":\"lib_user\"}',NULL,0,NULL,'2026-10-20 08:47:58',30),(107,'菜单管理',2,'com.ruoyi.web.controller.system.SysMenuController.edit()','PUT',1,'admin','研发部门','/system/menu','127.0.0.1','内网IP','{\"children\":[],\"component\":\"system/liuser/index\",\"createTime\":\"2026-10-20 08:49:02\",\"icon\":\"#\",\"isCache\":\"0\",\"isFrame\":\"1\",\"menuId\":2012,\"menuName\":\"图书读者\",\"menuType\":\"C\",\"orderNum\":1,\"params\":{},\"parentId\":3,\"path\":\"user\",\"per